function referenceClock(){document.querySelectorAll('[data-reference-top3]').forEach(box=>{const rows=[...box.querySelectorAll('[data-reference-candidate]')];const available=rows.filter(r=>Date.parse(r.dataset.referenceKickoff)>Date.now());let formal=0,fallback=0;rows.forEach(r=>r.hidden=true);available.slice(0,3).forEach(r=>{r.hidden=false;r.dataset.type==='formal'?formal++:fallback++;});box.querySelector('[data-reference-counts]').textContent='当前未开赛候选：正式'+formal+'场＋保底'+fallback+'场'+(formal+fallback<3?'（不足三场，不凑数）':'');});}referenceClock();setInterval(referenceClock,1000);const choose=document.querySelector('#date-choice');choose?.addEventListener('change',()=>location.assign(choose.value));const mark=document.querySelector('[data-revision]');function clock(){document.querySelectorAll('[data-kickoff]').forEach(e=>{if(e.dataset.final==='true')return;e.textContent=Date.now()<Date.parse(e.dataset.kickoff)?'尚未到计划开球时间':'已到计划开球时间，赛况待核验';});}clock();setInterval(clock,60000);const root=new URL('.',document.currentScript.src);async function check(){try{const r=await fetch(new URL('site-manifest.json?t='+Date.now(),root),{cache:'no-store'});if(!r.ok)return;const m=await r.json();if(mark?.dataset.latest==='true'&&m.revision!==mark.dataset.revision){const u=new URL('index.html',root);u.searchParams.set('v',m.revision);location.replace(u);}}catch{}}setInterval(check,60000);